public struct LearningProgress: Codable, Equatable, Sendable {
    public var completedCourses: Set<String> = []
    public var completedLessons: Set<String> = []
    public init() {}
    enum CodingKeys: String, CodingKey { case completedCourses, completedLessons }
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        completedCourses = try c.decode(Set<String>.self, forKey: .completedCourses)
        completedLessons = try c.decodeIfPresent(Set<String>.self, forKey: .completedLessons) ?? []
    }
    public func isComplete(_ lesson: LessonDefinition, in course: Course) -> Bool {
        completedCourses.contains(course.id) || completedLessons.contains(course.id + "/" + lesson.id)
    }
    public func canStart(_ index: Int, in course: Course) -> Bool {
        course.lessons.indices.contains(index) && course.lessons.prefix(index).allSatisfy { isComplete($0, in: course) }
    }
    public mutating func finish(_ index: Int, in course: Course) {
        guard canStart(index, in: course) else { return }
        completedLessons.insert(course.id + "/" + course.lessons[index].id)
        if course.lessons.allSatisfy({ isComplete($0, in: course) }) { completedCourses.insert(course.id) }
    }
}
public struct ProgressStore: Sendable {
